'use client';
import {useEffect,useMemo,useRef,useState} from 'react';
import {Activity,ArrowLeft,ArrowRight,BookOpen,Building2,CalendarDays,CheckCircle2,ChevronLeft,ChevronRight,ClipboardList,FileText,GraduationCap,LayoutDashboard,MapPin,Megaphone,Menu,Plus,Search,Settings,ShieldCheck,Star,Trophy,Users,X,Eye,Info} from 'lucide-react';
import type {LucideIcon} from 'lucide-react';
type Section='overview'|'users'|'centers'|'classes'|'roadmaps'|'materials'|'exams'|'teachers'|'ads'|'honors'|'settings'|'audit';
type Row={id:string;title:string;sub:string;owner:string;region:string;status:string;detail:string};
const navigation:{id:Section;label:string;icon:LucideIcon;group:string}[]=[
{id:'overview',label:'Tổng quan',icon:LayoutDashboard,group:'VẬN HÀNH'},
{id:'users',label:'Người dùng & giám hộ',icon:Users,group:'VẬN HÀNH'},
{id:'centers',label:'Trung tâm & đối tác',icon:Building2,group:'VẬN HÀNH'},
{id:'classes',label:'Lớp học',icon:GraduationCap,group:'ĐÀO TẠO'},
{id:'roadmaps',label:'Chương trình & lộ trình',icon:BookOpen,group:'ĐÀO TẠO'},
{id:'materials',label:'Tài liệu',icon:FileText,group:'ĐÀO TẠO'},
{id:'exams',label:'Luyện đề & ngân hàng câu',icon:ClipboardList,group:'ĐÀO TẠO'},
{id:'teachers',label:'Giáo viên đồng hành',icon:Users,group:'ĐÀO TẠO'},
{id:'ads',label:'Quảng cáo khu vực',icon:Megaphone,group:'NỘI DUNG & HỆ THỐNG'},
{id:'honors',label:'Bảng vàng thành tích',icon:Trophy,group:'NỘI DUNG & HỆ THỐNG'},
{id:'settings',label:'Cấu hình & phân quyền',icon:Settings,group:'NỘI DUNG & HỆ THỐNG'},
{id:'audit',label:'Nhật ký & hỗ trợ',icon:Activity,group:'NỘI DUNG & HỆ THỐNG'}];
const demoClasses=[
 {title:'Củng cố nền tảng Toán 9',grade:9,mode:'Trực tuyến'},
 {title:'Toán tư duy lớp 6',grade:6,mode:'Tại trung tâm'},
 {title:'Ôn thi vào lớp 10',grade:9,mode:'Kết hợp'},
 {title:'Hình học lớp 8',grade:8,mode:'Trực tuyến'},
 {title:'Toán lớp 5 theo chủ đề',grade:5,mode:'Tại trung tâm'},
 {title:'Bồi dưỡng Toán lớp 10',grade:10,mode:'Kết hợp'},
];
const titles:Record<string,string[]>={users:['Học sinh mẫu 01','Phụ huynh mẫu 02','Giáo viên mẫu 03','Học sinh mẫu 04','Giám hộ mẫu 05','Giáo viên mẫu 06','Học sinh mẫu 07'],centers:['Trung tâm mẫu A','Đơn vị đồng hành mẫu B','Cơ sở đào tạo mẫu C','Trung tâm mẫu D','Đối tác nội dung mẫu E','Cơ sở mẫu F'],classes:demoClasses.map(c=>c.title),roadmaps:['Nền tảng lớp 9','Lộ trình hình học lớp 7','Ôn tập học kỳ lớp 6','Chinh phục lớp 10','Tư duy Toán tiểu học','Chuyên đề đại số'],materials:['Phiếu học tập căn thức','Chuyên đề tam giác','Bộ công thức đại số','Tài liệu ôn vào lớp 10','Bài tập tư duy lớp 5','Hướng dẫn giải theo chủ đề'],exams:['Khảo sát đầu vào lớp 9','Đề ôn tập học kỳ','Bộ câu hỏi hình học','Luyện đề vào lớp 10','Đánh giá kiến thức nền','Đề luyện theo chuyên đề'],teachers:['Giáo viên mẫu 01','Giáo viên mẫu 02','Giáo viên mẫu 03','Giáo viên mẫu 04','Giáo viên mẫu 05','Giáo viên mẫu 06'],ads:['Giới thiệu lớp học tại khu vực A','Thông tin đơn vị khu vực B','Lịch tư vấn học tập mẫu','Thông báo khóa học mẫu','Chuyên đề cuối tuần mẫu','Giới thiệu học liệu mẫu'],honors:['Hồ sơ thành tích mẫu 01','Hồ sơ thành tích mẫu 02','Hồ sơ thành tích mẫu 03','Hồ sơ thành tích mẫu 04','Hồ sơ thành tích mẫu 05','Hồ sơ thành tích mẫu 06'],audit:['Yêu cầu hỗ trợ mẫu 01','Kiểm tra nội dung mẫu','Yêu cầu cập nhật hồ sơ mẫu','Ghi nhận thao tác mẫu','Hỗ trợ lớp học mẫu','Rà soát quyền mẫu']};
const details:Record<string,string>={users:'Vai trò, tỉnh/thành, tên trường và liên kết giám hộ cần được xác thực bởi hệ thống thật.',centers:'Hồ sơ đơn vị, địa bàn được cấp và người phụ trách. Không tự mở rộng quyền qua giao diện.',classes:'Lớp 9 · Hình thức trực tuyến · Giáo viên đứng lớp mẫu · Trung tâm mẫu · Giáo viên đồng hành mẫu. Chưa có đánh giá sao thật.',roadmaps:'Mục tiêu học tập, lớp, chuyên đề, thứ tự bài và trạng thái duyệt nội dung.',materials:'Tác giả mẫu · Đơn vị mẫu · PDF · Phạm vi toàn quốc. Chưa có tệp học liệu để tải.',exams:'Giáo viên biên soạn mẫu · Luyện trực tuyến · Đơn vị quản lý mẫu. Chưa có câu hỏi hoặc kết quả chấm thật.',teachers:'Thông tin chuyên môn, trung tâm quản lý, địa bàn và lớp đồng hành cần được xác minh.',ads:'Dòng quảng cáo, đơn vị, địa bàn và thời gian phát hành cần được duyệt. Nút trong bản này không xuất bản quảng cáo.',honors:'Học sinh mẫu · Lớp 9 · Tỉnh/thành mẫu · Điểm và danh hiệu chỉ minh họa; cần minh chứng trước công bố.',audit:'Đây là tình huống mẫu, không phải nhật ký hệ thống hoặc yêu cầu của người dùng thật.'};
function makeRows(s:Section):Row[]{return(titles[s]||[]).map((title,i)=>({id:`DEMO-${s.toUpperCase()}-${String(i+1).padStart(2,'0')}`,title,sub:s==='users'?['Học sinh','Phụ huynh','Giáo viên'][i%3]:s==='classes'?`${demoClasses[i].mode} · Lớp ${demoClasses[i].grade}`:'Dữ liệu minh họa · Chưa phát hành',owner:`Đơn vị mẫu ${String.fromCharCode(65+i%3)}`,region:`Khu vực mẫu ${String.fromCharCode(65+i%3)}`,status:['Chờ duyệt','Bản nháp','Đã rà soát'][i%3],detail:s==='classes'?`Lớp ${demoClasses[i].grade} · Hình thức ${demoClasses[i].mode.toLocaleLowerCase('vi')} · Giáo viên đứng lớp mẫu · Đơn vị mẫu ${String.fromCharCode(65+i%3)} · Giáo viên đồng hành mẫu.${i===2?' Dành cho học sinh lớp 9 ôn thi vào lớp 10.':''} Chưa có đánh giá sao thật.`:details[s]||''}));}
const statusClass=(s:string)=>s==='Chờ duyệt'?'pending':s==='Đã rà soát'?'reviewed':'draft';
export default function AdminDashboard(){
 const[section,setSection]=useState<Section>('overview');const[search,setSearch]=useState('');const[status,setStatus]=useState('all');const[page,setPage]=useState(1);const[mobile,setMobile]=useState(false);const[selected,setSelected]=useState<Row|null>(null);const[form,setForm]=useState(false);const modal=useRef<HTMLDialogElement>(null);const menuButton=useRef<HTMLButtonElement>(null);
 useEffect(()=>{const sync=()=>{const id=new URLSearchParams(location.search).get('section');setSection(navigation.some(n=>n.id===id)?id as Section:'overview');setSearch('');setStatus('all');setPage(1);setMobile(false);};sync();window.addEventListener('popstate',sync);return()=>window.removeEventListener('popstate',sync)},[]);
 useEffect(()=>{if(selected||form)modal.current?.showModal();else modal.current?.close()},[selected,form]);
 useEffect(()=>{if(!mobile)return;const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!modal.current?.open){e.preventDefault();setMobile(false);menuButton.current?.focus();}};document.addEventListener('keydown',onKey);return()=>document.removeEventListener('keydown',onKey)},[mobile]);
 const active=navigation.find(n=>n.id===section)!;const rows=useMemo(()=>makeRows(section),[section]);const filtered=rows.filter(r=>(status==='all'||r.status===status)&&`${r.title} ${r.id} ${r.owner} ${r.region}`.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));const pages=Math.max(1,Math.ceil(filtered.length/5));const visible=filtered.slice((page-1)*5,page*5);
 function navigate(id:Section){history.pushState({},'',id==='overview'?'/admin':`/admin?section=${id}`);setSection(id);setPage(1);setSearch('');setStatus('all');setMobile(false)}
 function close(){setSelected(null);setForm(false)}
 return <div className="admin-app">
 <a href="#admin-main" className="admin-skip">Đến nội dung quản trị</a>
 <aside id="admin-sidebar" className={`admin-sidebar ${mobile?'is-open':''}`} aria-label="Menu quản trị">
 <a className="admin-brand" href="/"><GraduationCap size={36}/><div><b>TOÁN <span>ÔNTHI<i>360</i></span></b><small>TT Bồi dưỡng HSG Nguyễn Viết Xuân</small></div></a>
 <div className="admin-workspace"><ShieldCheck size={20}/><div><strong>Không gian quản trị</strong><small>Bản thiết kế · Chưa xác thực</small></div><button className="admin-mobile-close" onClick={()=>setMobile(false)} aria-label="Đóng menu quản trị"><X size={20}/></button></div>
 <nav>{navigation.map((n,i)=><div key={n.id}>{(i===0||navigation[i-1].group!==n.group)&&<p className="admin-nav-label">{n.group}</p>}<button aria-current={section===n.id?'page':undefined} onClick={()=>navigate(n.id)} className={section===n.id?'active':''}><n.icon size={18}/><span>{n.label}</span>{section===n.id&&<ChevronRight size={15}/>}</button></div>)}</nav>
 <div className="admin-sidebar-note"><Info size={17}/><span>Giao diện mẫu, không kết nối dữ liệu hay cấp quyền quản trị thật.</span></div>
 <a className="admin-back" href="/"><ArrowLeft size={16}/> Xem trang chủ</a>
 </aside>
 {mobile&&<button className="admin-backdrop" aria-label="Ẩn menu quản trị" onClick={()=>setMobile(false)}/>}
 <div className="admin-shell"><header className="admin-top"><button ref={menuButton} aria-expanded={mobile} aria-controls="admin-sidebar" className="admin-menu-button" onClick={()=>setMobile(v=>!v)} aria-label="Mở menu quản trị"><Menu size={22}/></button><div className="admin-crumb">Quản trị <ChevronRight size={13}/><strong>{active.label}</strong></div><span className="admin-demo-badge">CHẾ ĐỘ MINH HỌA</span><a href="/" className="admin-top-home">Trang chủ <ArrowRight size={15}/></a></header>
 <main id="admin-main" className="admin-main"><div className="admin-heading"><div><span className="admin-eyebrow">TOÁN ÔN THI 360 · QUẢN TRỊ</span><h1>{active.label}</h1><p>{section==='overview'?'Theo dõi vận hành, nội dung và những việc cần xử lý trong một không gian.':'Tìm kiếm, theo dõi và xem cấu trúc quản lý phù hợp từng loại nội dung.'}</p></div>{!['overview','settings'].includes(section)&&<button className="admin-btn primary" onClick={()=>setForm(true)}><Plus size={17}/> Xem biểu mẫu</button>}</div>
 <div className="admin-disclaimer"><ShieldCheck size={17}/><span>Toàn bộ hồ sơ và số liệu bên dưới là <b>dữ liệu minh họa</b>. Chưa kết nối API, xác thực, phân quyền hoặc thao tác lưu/xuất bản.</span></div>
 {section==='overview'?<>
 <section className="admin-welcome"><div><span className="admin-eyebrow">CÙNG NHAU XÂY DỰNG MÔI TRƯỜNG HỌC TỐT</span><h2>Mỗi nội dung tốt,<br/>một bước tiến cho học sinh.</h2><p>Ưu tiên chất lượng học liệu, hồ sơ được xác minh và trải nghiệm học tập rõ ràng.</p><button className="admin-btn primary" onClick={()=>navigate('materials')}>Rà soát học liệu <ArrowRight size={16}/></button></div><img src="/assets/toan/catalog-classes-v5.webp" alt="Minh họa lớp học Toán"/></section>
 <section className="admin-stats" aria-label="Tổng quan dữ liệu minh họa">{[{label:'Thành viên mẫu',value:128,icon:Users,note:'Học sinh · Phụ huynh · Giáo viên'},{label:'Lớp học mẫu',value:24,icon:GraduationCap,note:'Trực tuyến & tại trung tâm'},{label:'Học liệu mẫu',value:86,icon:BookOpen,note:'Tài liệu · Chuyên đề · Lộ trình'},{label:'Mục chờ rà soát mẫu',value:12,icon:ClipboardList,note:'Nội dung & hồ sơ minh họa'}].map((s,i)=><article key={s.label} className={`admin-stat tone-${i}`}><span><s.icon size={22}/></span><div><p>{s.label}</p><strong>{s.value}</strong><small>{s.note}</small></div></article>)}</section>
 <div className="admin-overview-grid"><section className="admin-panel"><div className="admin-panel-head"><h2>Cần rà soát</h2><span className="admin-soft-label">Tình huống mẫu</span></div>{[{s:'materials',name:'Học liệu chờ duyệt',note:'Kiểm tra nội dung, tác giả và quyền sử dụng',icon:FileText},{s:'teachers',name:'Hồ sơ giáo viên',note:'Đối chiếu đơn vị và thông tin chuyên môn',icon:Users},{s:'ads',name:'Quảng cáo khu vực',note:'Rà soát nội dung, lịch và địa bàn được cấp',icon:Megaphone}].map(a=><button key={a.s} className="admin-action-row" onClick={()=>navigate(a.s as Section)}><span><a.icon size={20}/></span><div><strong>{a.name}</strong><small>{a.note}</small></div><ChevronRight size={17}/></button>)}</section>
 <section className="admin-panel"><div className="admin-panel-head"><h2>Truy cập nhanh</h2><Star size={18}/></div><div className="admin-quick-grid">{navigation.filter(n=>['classes','roadmaps','centers','honors'].includes(n.id)).map(n=><button key={n.id} onClick={()=>navigate(n.id)}><n.icon size={23}/><strong>{n.label}</strong><span>Xem quản lý <ArrowRight size={13}/></span></button>)}</div></section></div>
 <section className="admin-panel admin-readiness"><div><CheckCircle2 size={24}/><div><h2>Trước khi vận hành thật</h2><p>Kết nối dữ liệu, xác thực và kiểm tra quyền theo đơn vị cần hoàn tất trước khi sử dụng.</p></div></div><button className="admin-btn soft" onClick={()=>navigate('settings')}>Xem cấu hình <ArrowRight size={15}/></button></section>
 </>:section==='settings'?<section className="admin-settings-grid">{[{icon:ShieldCheck,title:'Quyền & phạm vi đơn vị',text:'Kiểm tra vai trò, đơn vị và địa bàn ở backend. Không cấp quyền chỉ bằng lựa chọn trên giao diện.',fields:['Admin nền tảng','Quản lý trung tâm','Chuyên môn & hỗ trợ']},{icon:MapPin,title:'Khu vực & quảng cáo',text:'Đơn vị thành viên gửi đề nghị. Người có quyền duyệt kiểm tra phạm vi, lịch và đích liên kết.',fields:['Địa bàn được cấp','Luồng gửi duyệt','Lịch phát hành']},{icon:Settings,title:'Thông tin công cộng',text:'Logo, thông tin đơn vị, chocon, SAT và nội dung trang chủ cần được xác nhận trước công bố.',fields:['Tên thương hiệu','Liên kết hệ sinh thái','SEO & chính sách']},{icon:Activity,title:'Kết nối & nhật ký',text:'Chưa cấu hình API hoặc ghi nhật ký thật. Không yêu cầu khóa API, mật khẩu hay dữ liệu nhạy cảm tại đây.',fields:['API chưa kết nối','Auth chưa kết nối','Nhật ký chưa kết nối']}].map(c=><article className="admin-panel" key={c.title}><c.icon size={25}/><h2>{c.title}</h2><p>{c.text}</p>{c.fields.map(f=><div className="admin-setting-line" key={f}><span>{f}</span><small>Chờ cấu hình</small></div>)}</article>)}</section>:<section className="admin-panel admin-list">
 <div className="admin-list-tools"><label className="admin-search"><Search size={18}/><input aria-label="Tìm kiếm danh sách" placeholder="Tìm tên, mã hoặc đơn vị…" value={search} onChange={e=>{setSearch(e.target.value);setPage(1)}}/></label><label className="admin-filter">Trạng thái<select aria-label="Lọc trạng thái" value={status} onChange={e=>{setStatus(e.target.value);setPage(1)}}><option value="all">Tất cả trạng thái</option><option>Chờ duyệt</option><option>Bản nháp</option><option>Đã rà soát</option></select></label></div>
 <div className="admin-table-wrap" tabIndex={0} aria-label="Bảng quản lý có thể cuộn ngang"><table><thead><tr><th>{section==='users'?'Người dùng':section==='centers'?'Đơn vị':'Tên nội dung / hồ sơ'}</th><th>Đơn vị quản lý</th><th>Khu vực</th><th>Trạng thái mẫu</th><th><span className="admin-sr">Thao tác</span></th></tr></thead><tbody>{visible.map(r=><tr key={r.id}><td><strong>{r.title}</strong><small>{r.id}</small><small>{r.sub}</small></td><td>{r.owner}</td><td><span className="admin-region"><MapPin size={13}/>{r.region}</span></td><td><span className={`admin-status ${statusClass(r.status)}`}>{r.status}</span></td><td><button className="admin-view" aria-label={`Xem ${r.title}`} onClick={()=>setSelected(r)}><Eye size={17}/><span>Chi tiết</span></button></td></tr>)}</tbody></table>{!visible.length&&<div className="admin-empty"><Search size={30}/><h3>Chưa có mục phù hợp</h3><p>Thử thay từ khóa hoặc bộ lọc.</p><button className="admin-btn soft" onClick={()=>{setSearch('');setStatus('all');setPage(1)}}>Xóa bộ lọc</button></div>}</div>
 <div className="admin-pagination"><span>{filtered.length?`${(page-1)*5+1}–${Math.min(page*5,filtered.length)} / ${filtered.length} mục mẫu`:'0 mục phù hợp'}</span><div><button aria-label="Trang trước" disabled={page===1} onClick={()=>setPage(p=>p-1)}><ChevronLeft size={17}/></button>{Array.from({length:pages},(_,i)=><button key={i} aria-current={page===i+1?'page':undefined} className={page===i+1?'active':''} onClick={()=>setPage(i+1)}>{i+1}</button>)}<button aria-label="Trang sau" disabled={page===pages} onClick={()=>setPage(p=>p+1)}><ChevronRight size={17}/></button></div></div>
 </section>}
 <footer className="admin-footer"><span>TOÁN ÔN THI 360 · Không gian quản trị</span><span>Thiết kế thử nghiệm · Chưa có quyền vận hành thật</span></footer>
 </main></div>
 <dialog ref={modal} className="admin-dialog" onCancel={e=>{e.preventDefault();close()}} onClick={e=>{if(e.target===e.currentTarget)close()}}><div className="admin-dialog-head"><div><span className="admin-eyebrow">DỮ LIỆU MINH HỌA</span><h2>{form?'Biểu mẫu '+active.label:selected?.title}</h2></div><button aria-label="Đóng chi tiết" onClick={close}><X size={22}/></button></div>{selected?<><p className="admin-modal-copy">{selected.detail}</p><dl>{[['Mã mẫu',selected.id],['Đơn vị',selected.owner],['Khu vực',selected.region],['Trạng thái mẫu',selected.status]].map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl></>:<div className="admin-demo-form"><p>Minh họa cấu trúc nhập liệu. Các trường đang khóa; không thu thập hoặc lưu dữ liệu.</p><label>Tên nội dung / hồ sơ<input disabled placeholder="Tên mẫu"/></label><div><label>Đơn vị<select disabled><option>Chọn đơn vị được cấp</option></select></label><label>Tỉnh/thành<select disabled><option>Chọn phạm vi được cấp</option></select></label></div><label>Mô tả<textarea disabled placeholder="Nội dung cần duyệt trước khi công bố"/></label></div>}<div className="admin-dialog-note"><Info size={16}/>Chưa có API và phân quyền. Không có thay đổi nào được lưu hoặc công bố.</div><div className="admin-dialog-actions"><button className="admin-btn soft" onClick={close}>Đóng</button>{form&&<button className="admin-btn primary" disabled>Lưu bản nháp · Chưa kết nối</button>}</div></dialog>
 </div>
}
